package app.orbit.couple;
import org.junit.Test;
import static org.junit.Assert.*;
import javax.crypto.KeyGenerator;
public class WidgetSnapshotTest {
 static final String OWNER="11111111-1111-4111-8111-111111111111",COUPLE="22222222-2222-4222-8222-222222222222",ID="33333333-3333-4333-8333-333333333333";
 WidgetSnapshot photo()throws Exception{return new WidgetSnapshot(OWNER,COUPLE,"photo",ID,2,1000,0,"Kept photo","",new byte[]{1,2,3});}
 @Test public void snapshotsRequireTheSameAccountFreshDataAndEveryPrivacyGate()throws Exception{WidgetSnapshot p=photo();assertTrue(p.visible(OWNER,false,false,true,1001));assertFalse(p.visible(ID,false,false,true,1001));assertFalse(p.visible(OWNER,true,false,true,1001));assertFalse(p.visible(OWNER,false,true,true,1001));assertFalse(p.visible(OWNER,false,false,false,1001));assertFalse(p.visible(OWNER,false,false,true,999));assertFalse(p.visible(OWNER,false,false,true,1001+WidgetSnapshot.MAX_AGE));}
 @Test public void aDifferentKeepRevisionOrCoupleCannotReuseAnOlderPreview()throws Exception{WidgetSnapshot p=photo();assertTrue(p.matches(OWNER,COUPLE,ID,"photo",2));assertFalse(p.matches(OWNER,COUPLE,ID,"photo",3));assertFalse(p.matches(OWNER,ID,ID,"photo",2));}
 @Test public void aPastPlanNeverRendersAsUpcoming()throws Exception{WidgetSnapshot p=new WidgetSnapshot(OWNER,COUPLE,"plan",ID,1,1000,2000,"Picnic 🌿","Tomorrow",new byte[0]);assertTrue(p.visible(OWNER,false,false,true,1500));assertFalse(p.visible(OWNER,false,false,true,2000));assertFalse(p.visible(OWNER,false,false,true,2500));}
 @Test public void boundedUnicodeRecordsRoundtripAndRejectTruncationTrailingBytesAndUnknownFormats()throws Exception{WidgetSnapshot p=new WidgetSnapshot(OWNER,COUPLE,"plan",ID,2,1000,5000,"A day 🌿","5 Nov",new byte[0]);assertEquals(p.title,WidgetSnapshot.unpack(p.pack()).title);byte[] photo=photo().pack();assertArrayEquals(new byte[]{1,2,3},WidgetSnapshot.unpack(photo).image);assertThrows(Exception.class,()->WidgetSnapshot.unpack(java.util.Arrays.copyOf(photo,photo.length-1)));assertThrows(Exception.class,()->WidgetSnapshot.unpack(java.util.Arrays.copyOf(photo,photo.length+1)));photo[3]=2;assertThrows(Exception.class,()->WidgetSnapshot.unpack(photo));}
 @Test public void encryptedFilesRejectDifferentOwnersAndTampering()throws Exception{KeyGenerator generator=KeyGenerator.getInstance("AES");generator.init(256);var key=generator.generateKey();var record=new KeepsakeRecord("{}",photo().pack());byte[] data=record.encrypt(key,OWNER+":"+COUPLE+":widget-v1");assertEquals(ID,WidgetSnapshot.unpack(KeepsakeRecord.decrypt(data,key,OWNER+":"+COUPLE+":widget-v1").media).id);assertThrows(Exception.class,()->KeepsakeRecord.decrypt(data,key,ID+":"+COUPLE+":widget-v1"));data[data.length-1]^=1;assertThrows(Exception.class,()->KeepsakeRecord.decrypt(data,key,OWNER+":"+COUPLE+":widget-v1"));}
 @Test public void oversizedImagesAndInvalidKindsAreRejected()throws Exception{assertThrows(Exception.class,()->new WidgetSnapshot(OWNER,COUPLE,"photo",ID,1,1,0,"Photo","",new byte[WidgetSnapshot.MAX_IMAGE+1]));assertThrows(Exception.class,()->new WidgetSnapshot(OWNER,COUPLE,"private",ID,1,1,0,"Private","",new byte[0]));}
 @Test public void serverTimestampsRetainOffsetsAndFractionalSecondsAreSafe()throws Exception{assertEquals(WidgetSnapshot.instant("2026-11-05T12:00:00Z"),WidgetSnapshot.instant("2026-11-05T17:30:00.123456+05:30"));assertThrows(Exception.class,()->WidgetSnapshot.instant("2026-02-30T12:00:00Z"));assertThrows(Exception.class,()->WidgetSnapshot.instant("2026-11-05"));}
}
